package p_root
import("testing";"math/big";"math/rand"; "sync/atomic"; rt "gopurs/output/gopurs_runtime")
var congruenceSink int64
var scalarBenchLimit int64 = 900
//go:noinline
func prototypeSelectedSum(lower,upper,divisor,residue,seed int64) int64 {
 first:=lower+(residue-lower%divisor+divisor)%divisor
 if first>upper{return seed}
 count:=(upper-first)/divisor+1
 last:=first+(count-1)*divisor
 return int64(int32(seed+count*(first+last)/2))
}
func prototypeSelectedLoop(lower,upper,divisor,residue,seed int64) int64 {
 for v:=upper;v>=lower;v-- {if rt.IntMod(v,divisor)==residue {seed=rt.IntAdd(seed,v)}}
 return seed
}
//go:noinline
func prototypeSelectedStride(lower,upper,divisor,residue,seed int64) int64 {
 first:=lower+(residue-lower%divisor+divisor)%divisor
 for v:=first;v<=upper;v+=divisor {seed=rt.IntAdd(seed,v)}
 return seed
}
func bigCongruenceOracle(lower,upper,divisor,residue,seed int64) int64 {
 firstK:=(lower+divisor-1-residue)/divisor
 lastK:=new(big.Int).Div(big.NewInt(upper-residue),big.NewInt(divisor)).Int64()
 if lastK<firstK{return seed}
 count:=lastK-firstK+1
 indices:=new(big.Int).Mul(big.NewInt(count),big.NewInt(firstK+lastK));indices.Div(indices,big.NewInt(2))
 result:=new(big.Int).Mul(indices,big.NewInt(divisor));result.Add(result,new(big.Int).Mul(big.NewInt(count),big.NewInt(residue)));result.Add(result,big.NewInt(seed))
 return int64(int32(result.Int64()))
}
func TestCongruencePrototype(t *testing.T) {
 rng:=rand.New(rand.NewSource(2186))
 for i:=0;i<10000;i++ {
  lower:=int64(rng.Intn(30)+1);upper:=lower+int64(rng.Intn(1500)-20);divisor:=int64(rng.Intn(19)+1);residue:=int64(rng.Intn(int(divisor)));seed:=int64(int32(rng.Uint32()))
  want:=prototypeSelectedLoop(lower,upper,divisor,residue,seed)
  for _,got:=range []int64{prototypeSelectedSum(lower,upper,divisor,residue,seed),prototypeSelectedStride(lower,upper,divisor,residue,seed),bigCongruenceOracle(lower,upper,divisor,residue,seed)} {if got!=want{t.Fatalf("%d %d %d %d %d got=%d want=%d",lower,upper,divisor,residue,seed,got,want)}}
 }
 for _,c:=range [][5]int64{{1,2147483647,1,0,2147483647},{1,2147483647,2,0,-2147483648},{1,2147483647,3,2,17},{2147483639,2147483647,2,1,-2147483648},{2147483647,2147483647,2147483647,2147483646,2147483647},{2147483647,2147483647,2147483647,0,1}} {
  got:=prototypeSelectedSum(c[0],c[1],c[2],c[3],c[4]);want:=bigCongruenceOracle(c[0],c[1],c[2],c[3],c[4]);if got!=want{t.Fatalf("extreme %v got=%d want=%d",c,got,want)}
 }
 for n:=int64(-4);n<=1025;n++ {got:=Call_Test_ListOps_sumEvens(n);want:=prototypeSelectedSum(1,n,2,0,0);if got!=want{t.Fatalf("generated n=%d got=%d want=%d",n,got,want)}}
}
func BenchmarkListScalarGenerated(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{congruenceSink=Call_Test_ListOps_sumEvens(atomic.LoadInt64(&scalarBenchLimit))}}
func BenchmarkListScalarStride(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{congruenceSink=prototypeSelectedStride(1,atomic.LoadInt64(&scalarBenchLimit),2,0,0)}}
func BenchmarkListScalarFormula(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{congruenceSink=prototypeSelectedSum(1,atomic.LoadInt64(&scalarBenchLimit),2,0,0)}}

